static const SplitflapBitmap& blankBitmap(SplitflapPart part) {
  const SplitflapRecord& blank = SPLITFLAP_RECORDS[sizeof(SPLITFLAP_RECORDS) / sizeof(SPLITFLAP_RECORDS[0]) - 1];
  if (part == SplitflapPart::Top) return blank.top;
  if (part == SplitflapPart::Bottom) return blank.bottom;
  return blank.full;
}

const SplitflapBitmap& splitflapBitmap(char ch, SplitflapPart part) {
  if (ch >= 'a' && ch <= 'z') ch = ch - 'a' + 'A';
  for (const SplitflapRecord& record : SPLITFLAP_RECORDS) {
    if (record.ch == ch) {
      if (part == SplitflapPart::Top) return record.top;
      if (part == SplitflapPart::Bottom) return record.bottom;
      return record.full;
    }
  }
  return blankBitmap(part);
}
